   198  void usbredirparser_destroy(struct usbredirparser *parser_pub)
   199  {
   200      struct usbredirparser_priv *parser =
   201          (struct usbredirparser_priv *)parser_pub;
   202      struct usbredirparser_buf *wbuf, *next_wbuf;
   203
   204      free(parser->data);
   205      parser->data = NULL;
   206
   207      wbuf = parser->write_buf;
   208      while (wbuf) {
   209          next_wbuf = wbuf->next;
   210          free(wbuf->buf);
   211          free(wbuf);
   212          wbuf = next_wbuf;
   213      }
   214
   215      if (parser->lock)
   216          parser->callb.free_lock_func(parser->lock);
   217
   218      free(parser);
   219  }
