   221  static int usbredirparser_caps_get_cap(struct usbredirparser_priv *parser,
   222      uint32_t *caps, int cap)
   223  {
   224      if (cap / 32 >= USB_REDIR_CAPS_SIZE) {
   225          ERROR("error request for out of bounds cap: %d", cap);
   226          return 0;
   227      }
   228      if (caps[cap / 32] & (1 << (cap % 32))) {
   229          return 1;
   230      } else {
   231          return 0;
   232      }
   233  }
