   272  static void usbredirparser_handle_hello(struct usbredirparser *parser_pub,
   273      struct usb_redir_hello_header *hello, uint8_t *data, int data_len)
   274  {
   275      struct usbredirparser_priv *parser =
   276          (struct usbredirparser_priv *)parser_pub;
   277      uint32_t *peer_caps = (uint32_t *)data;
   278      char buf[64];
   279      int i;
   280
   281      if (parser->have_peer_caps) {
   282          ERROR("Received second hello message, ignoring");
   283          return;
   284      }
   285
   286      /* In case hello->version is not 0 terminated (which would be a protocol
   287         violation)_ */
   288      strncpy(buf, hello->version, sizeof(buf));
   289      buf[sizeof(buf)-1] = '\0';
   290
   291      memset(parser->peer_caps, 0, sizeof(parser->peer_caps));
   292      if (data_len > sizeof(parser->peer_caps)) {
   293          data_len = sizeof(parser->peer_caps);
   294      }
   295      for (i = 0; i < data_len / sizeof(uint32_t); i++) {
   296          parser->peer_caps[i] = peer_caps[i];
   297      }
   298      usbredirparser_verify_caps(parser, parser->peer_caps, "peer");
   299      parser->have_peer_caps = 1;
   300
   301      INFO("Peer version: %s, using %d-bits ids", buf,
   302           usbredirparser_using_32bits_ids(parser_pub) ? 32 : 64);
   303
   304      /* Added in 0.3.2, so no guarantee it is there */
   305      if (parser->callb.hello_func)
   306          parser->callb.hello_func(parser->callb.priv, hello);
   307  }
