   317  static int usbredirparser_get_type_header_len(
   318      struct usbredirparser *parser_pub, int32_t type, int send)
   319  {
   320      struct usbredirparser_priv *parser =
   321          (struct usbredirparser_priv *)parser_pub;
   322      int command_for_host = 0;
   323
   324      if (parser->flags & usbredirparser_fl_usb_host) {
   325          command_for_host = 1;
   326      }
   327      if (send) {
   328          command_for_host = !command_for_host;
   329      }
   330
   331      switch (type) {
   332      case usb_redir_hello:
   333          return sizeof(struct usb_redir_hello_header);
   334      case usb_redir_device_connect:
   335          if (!command_for_host) {
   336              if (usbredirparser_have_cap(parser_pub,
   337                                      usb_redir_cap_connect_device_version) &&
   338                  usbredirparser_peer_has_cap(parser_pub,
   339                                      usb_redir_cap_connect_device_version)) {
   340                  return sizeof(struct usb_redir_device_connect_header);
   341              } else {
   342                  return sizeof(struct usb_redir_device_connect_header_no_device_version);
   343              }
   344          } else {
   345              return -1;
   346          }
   347      case usb_redir_device_disconnect:
   348          if (!command_for_host) {
   349              return 0;
   350          } else {
   351              return -1;
   352          }
   353      case usb_redir_reset:
   354          if (command_for_host) {
   355              return 0; /* No packet type specific header */
   356          } else {
   357              return -1;
   358          }
   359      case usb_redir_interface_info:
   360          if (!command_for_host) {
   520              return sizeof(struct usb_redir_bulk_packet_header_16bit_length);
   521          }
   522      case usb_redir_iso_packet:
   523          return sizeof(struct usb_redir_iso_packet_header);
   524      case usb_redir_interrupt_packet:
   525          return sizeof(struct usb_redir_interrupt_packet_header);
   526      case usb_redir_buffered_bulk_packet:
   527          if (!command_for_host) {
   528              return sizeof(struct usb_redir_buffered_bulk_packet_header);
   529          } else {
   530              return -1;
   531          }
   532      default:
   533          return -1;
   534      }
   535  }
