   556  static int usbredirparser_verify_bulk_recv_cap(
   557      struct usbredirparser *parser_pub, int send)
   558  {
   559      struct usbredirparser_priv *parser =
   560          (struct usbredirparser_priv *)parser_pub;
   561
   562      if ((send && !usbredirparser_peer_has_cap(parser_pub,
   563                                                usb_redir_cap_bulk_receiving)) ||
   564          (!send && !usbredirparser_have_cap(parser_pub,
   565                                             usb_redir_cap_bulk_receiving))) {
   566          ERROR("error bulk_receiving without cap_bulk_receiving");
   567          return 0;
   568      }
   569      return 1; /* Verify ok */
   570  }
