   572  static int usbredirparser_verify_type_header(
   573      struct usbredirparser *parser_pub,
   574      int32_t type, void *header, uint8_t *data, int data_len, int send)
   575  {
   576      struct usbredirparser_priv *parser =
   577          (struct usbredirparser_priv *)parser_pub;
   578      int command_for_host = 0, expect_extra_data = 0;
   579      uint32_t length = 0;
   580      int ep = -1;
   581
   582      if (parser->flags & usbredirparser_fl_usb_host) {
   583          command_for_host = 1;
   584      }
   585      if (send) {
   586          command_for_host = !command_for_host;
   587      }
   588
   589      switch (type) {
   590      case usb_redir_interface_info: {
   591          struct usb_redir_interface_info_header *intf_info = header;
   592
   593          if (intf_info->interface_count > 32) {
   594              ERROR("error interface_count > 32");
   595              return 0;
   596          }
   597          break;
   598      }
   599      case usb_redir_start_interrupt_receiving: {
   600          struct usb_redir_start_interrupt_receiving_header *start_int = header;
   601
   602          if (!(start_int->endpoint & 0x80)) {
   603              ERROR("start int receiving on non input ep %02x",
   604                    start_int->endpoint);
   605              return 0;
   606          }
   607          break;
   608      }
   609      case usb_redir_stop_interrupt_receiving: {
   610          struct usb_redir_stop_interrupt_receiving_header *stop_int = header;
   611
   612          if (!(stop_int->endpoint & 0x80)) {
   613              ERROR("stop int receiving on non input ep %02x",
   614                    stop_int->endpoint);
   615              return 0;
   616          }
   617          break;
   618      }
   619      case usb_redir_interrupt_receiving_status: {
   620          struct usb_redir_interrupt_receiving_status_header *int_status = header;
   621
   622          if (!(int_status->endpoint & 0x80)) {
   623              ERROR("int receiving status for non input ep %02x",
   624                    int_status->endpoint);
   625              return 0;
   626          }
   627          break;
   628      }
   629      case usb_redir_filter_reject:
   630          if ((send && !usbredirparser_peer_has_cap(parser_pub,
   631                                               usb_redir_cap_filter)) ||
   632              (!send && !usbredirparser_have_cap(parser_pub,
   633                                               usb_redir_cap_filter))) {
   634              ERROR("error filter_reject without cap_filter");
   635              return 0;
   636          }
   637          break;
   638      case usb_redir_filter_filter:
   639          if ((send && !usbredirparser_peer_has_cap(parser_pub,
   640                                               usb_redir_cap_filter)) ||
   641              (!send && !usbredirparser_have_cap(parser_pub,
   642                                               usb_redir_cap_filter))) {
   643              ERROR("error filter_filter without cap_filter");
   644              return 0;
   645          }
   646          if (data_len < 1) {
   647              ERROR("error filter_filter without data");
   648              return 0;
   649          }
   650          if (data[data_len - 1] != 0) {
   651              ERROR("error non 0 terminated filter_filter data");
   652              return 0;
   653          }
   654          break;
   655      case usb_redir_device_disconnect_ack:
   656          if ((send && !usbredirparser_peer_has_cap(parser_pub,
   657                                       usb_redir_cap_device_disconnect_ack)) ||
   658              (!send && !usbredirparser_have_cap(parser_pub,
   659                                       usb_redir_cap_device_disconnect_ack))) {
   660              ERROR("error device_disconnect_ack without cap_device_disconnect_ack");
   661              return 0;
   662          }
   663          break;
   664      case usb_redir_start_bulk_receiving: {
   665          struct usb_redir_start_bulk_receiving_header *start_bulk = header;
   666
   667          if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
   668              return 0;
   669          }
   670          if (start_bulk->bytes_per_transfer > MAX_BULK_TRANSFER_SIZE) {
   671              ERROR("start bulk receiving length exceeds limits %u > %u",
   672                    start_bulk->bytes_per_transfer, MAX_BULK_TRANSFER_SIZE);
   673              return 0;
   674          }
   675          if (!(start_bulk->endpoint & 0x80)) {
   676              ERROR("start bulk receiving on non input ep %02x",
   677                    start_bulk->endpoint);
   678              return 0;
   679          }
   680          break;
   681      }
   682      case usb_redir_stop_bulk_receiving: {
   683          struct usb_redir_stop_bulk_receiving_header *stop_bulk = header;
   684
   685          if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
   686              return 0;
   687          }
   688          if (!(stop_bulk->endpoint & 0x80)) {
   689              ERROR("stop bulk receiving on non input ep %02x",
   690                    stop_bulk->endpoint);
   691              return 0;
   692          }
   693          break;
   694      }
   695      case usb_redir_bulk_receiving_status: {
   696          struct usb_redir_bulk_receiving_status_header *bulk_status = header;
   697
   698          if (!usbredirparser_verify_bulk_recv_cap(parser_pub, send)) {
   699              return 0;
   700          }
